from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.B, Direction.CLOCKWISE)
attachment = Motor(Port.C, Direction.CLOCKWISE)
drive_base = DriveBase(left_wheel, right_wheel, 56, 114)


# The main program starts here.
drive_base.settings(turn_acceleration=500)
drive_base.settings(turn_rate=100)
drive_base.straight(250, then=Stop.COAST)
drive_base.arc(100, angle=90, then=Stop.BRAKE)
drive_base.turn(45, then=Stop.BRAKE)
drive_base.settings(straight_speed=50)
drive_base.straight(50, then=Stop.BRAKE)
wait(250)
attachment.run_angle(500, 180, Stop.BRAKE)
wait(500)
attachment.run_angle(500, -180, Stop.BRAKE)
